"""``control_response``: step, impulse or ramp response of a transfer function or a state-space model, with the usual metrics.

Method
* A transfer function is realised in controllable canonical form (a state-space model); a state-space model is used as given.
* Continuous time: exact at the sample instants.  The unit step and the unit ramp are generated by an augmented system whose
  state contains the input (u' = 0, u(0) = 1 for the step; u' = c, c' = 0 for the ramp), so ``exp(M T)`` propagates the true
  input, not a zero-order-hold approximation.  The impulse is the initial condition x(0+) = B.
* Discrete time: the recursion x[k+1] = A x[k] + B u[k]; the impulse is the unit pulse at k = 0, the ramp u[k] = k T.
* Metrics (step): final value = DC gain of a stable system; rise time 10 % to 90 % of the final value; percent overshoot
  100 (peak - final) / |final|; settling time = last instant outside the +/- tolerance band (default 2 %) around the final value;
  steady-state error = 1 - final value for a unit step.  Times between samples are by linear interpolation, the peak by a
  parabola through three samples; they are as accurate as the sample step, the sample values themselves are exact.
"""

from __future__ import annotations

import json
import math
from typing import Annotated, Any

import numpy as np
from pydantic import Field

from eng_toolkit.contract import QuantityOut, ToolResult
from eng_toolkit.domains.control import _lti as lti
from eng_toolkit.domains.control import _poly as poly
from eng_toolkit.domains.control._common import (
    Computed,
    DomainIn,
    JobHandle,
    SampleTimeIn,
    build_tf,
    choice,
    clean,
    csv_text,
    domain_and_step,
    is_blank,
    numerical_checks,
    plain,
    plain_number,
    qty,
    run,
    stability_report,
    time_value,
    tf_out,
    whole_number,
)
from eng_toolkit.domains.control._server import server
from eng_toolkit.units import UnitsError

INPUTS = ("step", "impulse", "ramp")
MAX_MATRIX_TEXT = 20000

_POINTER_SS = "write state space as nested JSON lists, e.g. A '[[0, 1], [-2, -3]]', B '[[0], [1]]' (or '[0, 1]'), C '[[1, 0]]' (or '[1, 0]'), D '0'"


def _matrix(raw: Any, *, name: str) -> np.ndarray:
    if not isinstance(raw, str):
        raise UnitsError("input.invalid", f"'{name}' must be a JSON string; {_POINTER_SS}", {"param": name})
    if len(raw) > MAX_MATRIX_TEXT:
        raise UnitsError("input.out_of_range", f"'{name}' is {len(raw)} characters long; the limit is {MAX_MATRIX_TEXT}", {"param": name})
    try:
        value = json.loads(raw, parse_constant=lambda c: (_ for _ in ()).throw(ValueError(f"the JSON constant {c} is not a number")))
    except RecursionError as exc:
        raise UnitsError("input.invalid", f"'{name}' is nested too deeply; {_POINTER_SS}", {"param": name}) from exc
    except ValueError as exc:
        raise UnitsError("input.invalid", f"'{name}' is not valid JSON ({str(exc)[:80]}); {_POINTER_SS}", {"param": name}) from exc
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        value = [[value]]
    if not isinstance(value, list) or not value:
        raise UnitsError("input.invalid", f"'{name}' must be a non-empty list; {_POINTER_SS}", {"param": name})
    if all(isinstance(v, (int, float)) and not isinstance(v, bool) for v in value):
        value = [value]  # flat list -> one row; the caller reshapes B to a column
    if not all(isinstance(row, list) and row for row in value):
        raise UnitsError("input.invalid", f"'{name}' must be a list of numbers or a list of equal-length lists of numbers; {_POINTER_SS}", {"param": name})
    width = len(value[0])
    if any(len(row) != width for row in value):
        raise UnitsError("input.invalid", f"'{name}' has rows of different lengths", {"param": name})
    if len(value) > poly.MAX_ORDER or width > poly.MAX_ORDER:
        raise UnitsError("input.out_of_range", f"'{name}' is {len(value)} x {width}; the state-space order is limited to {poly.MAX_ORDER}", {"param": name, "limit_order": poly.MAX_ORDER})
    flat = [x for row in value for x in row]
    arr = poly.check_coefficients(flat, param=name) if all(not isinstance(x, list) for x in flat) else None
    if arr is None:
        raise UnitsError("input.invalid", f"'{name}' must contain only numbers; {_POINTER_SS}", {"param": name})
    return arr.reshape(len(value), width)


def state_space(a_raw: Any, b_raw: Any, c_raw: Any, d_raw: Any) -> tuple[np.ndarray, np.ndarray, np.ndarray, float]:
    a = _matrix(a_raw, name="state_a")
    if a.shape[0] != a.shape[1]:
        raise UnitsError("input.invalid", f"'state_a' must be square, got {a.shape[0]} x {a.shape[1]}", {"param": "state_a"})
    n = a.shape[0]
    b = _matrix(b_raw, name="state_b")
    if b.shape[0] == 1 and b.shape[1] == n and n > 1:
        b = b.reshape(n, 1)  # a flat list is one row; B is a column
    if b.shape != (n, 1):
        if b.shape[0] == n and b.shape[1] > 1:
            raise UnitsError("input.invalid", f"'state_b' has {b.shape[1]} columns: only one input (SISO) is supported, MIMO is not", {"param": "state_b"})
        raise UnitsError("input.invalid", f"'state_b' must be {n} x 1 (or a flat list of {n} numbers), got {b.shape[0]} x {b.shape[1]}", {"param": "state_b"})
    c = _matrix(c_raw, name="state_c")
    if c.shape != (1, n):
        if c.shape[1] == n and c.shape[0] > 1:
            raise UnitsError("input.invalid", f"'state_c' has {c.shape[0]} rows: only one output (SISO) is supported, MIMO is not", {"param": "state_c"})
        raise UnitsError("input.invalid", f"'state_c' must be 1 x {n} (or a flat list of {n} numbers), got {c.shape[0]} x {c.shape[1]}", {"param": "state_c"})
    d = _matrix(d_raw if not is_blank(d_raw) else "0", name="state_d")
    if d.shape != (1, 1):
        raise UnitsError("input.invalid", "'state_d' must be a single number (SISO)", {"param": "state_d"})
    return a, b, c, float(d[0, 0])


def _dc_gain_ss(a: np.ndarray, b: np.ndarray, c: np.ndarray, d: float, discrete: bool) -> float | None:
    n = a.shape[0]
    m = (np.eye(n) - a) if discrete else (-a)
    if abs(np.linalg.det(m)) < 1e-12 * max(1.0, np.linalg.norm(m, np.inf) ** n) or np.linalg.cond(m) > 1e12:
        return None
    return float((c @ np.linalg.solve(m, b))[0, 0] + d)


@server.tool(
    name="response",
    description=(
        "Time response of a SISO system to a unit step, impulse or ramp: either a transfer function (numerator, denominator as "
        "coefficient lists in descending powers or polynomial text) or a state-space model (state_a, state_b, state_c, state_d as nested "
        "JSON lists). Exact discretisation. Returns the response table as a CSV artifact (time,input,output; at most 100000 samples) and the "
        "metrics: rise time (10-90 %), peak value and time, percent overshoot, 2 % settling time (settling_tolerance), steady-state value "
        "and error. For an unstable system it reports 'unbounded' instead of failing. Time range auto-chosen from the slowest and fastest poles "
        "unless t_final / samples are given."
    ),
)
def response(
    numerator: Annotated[str, Field(description="Transfer-function numerator (descending coefficients, e.g. '[16]' or text '16'). Leave empty when using state space.")] = "",
    denominator: Annotated[str, Field(description="Transfer-function denominator, e.g. '[1, 4, 16]' or 's^2 + 4 s + 16'. Must be proper (order >= numerator order). Leave empty when using state space.")] = "",
    state_a: Annotated[str, Field(description="State-space A as nested JSON list (n x n), e.g. '[[0, 1], [-2, -3]]'. Use INSTEAD of numerator/denominator.")] = "",
    state_b: Annotated[str, Field(description="State-space B, n x 1 as '[[0],[1]]' or a flat list '[0, 1]'")] = "",
    state_c: Annotated[str, Field(description="State-space C, 1 x n as '[[1, 0]]' or a flat list '[1, 0]'")] = "",
    state_d: Annotated[str, Field(description="State-space D, a single number, default '0'")] = "0",
    domain: DomainIn = "continuous",
    sample_time: SampleTimeIn = "",
    input_type: Annotated[str, Field(description="'step' (default, unit step), 'impulse' or 'ramp' (unit slope)")] = "step",
    t_final: Annotated[str, Field(description="End time with unit, e.g. '5 s'. Empty = chosen from the poles.")] = "",
    samples: Annotated[int, Field(description="Number of time samples (0 = automatic, at most 100000)")] = 0,
    settling_tolerance: Annotated[float, Field(description="Settling band as a fraction of the final value, default 0.02 (2 %)")] = 0.02,
) -> ToolResult:
    inputs = {
        "numerator": numerator, "denominator": denominator, "state_a": state_a, "state_b": state_b, "state_c": state_c, "state_d": state_d,
        "domain": domain, "sample_time": sample_time, "input_type": input_type, "t_final": t_final, "samples": samples,
        "settling_tolerance": settling_tolerance,
    }

    def compute(handle: JobHandle) -> Computed:
        kind = choice(input_type, name="input_type", allowed=INPUTS)
        tol = plain_number(settling_tolerance, name="settling_tolerance", lo=1e-6, hi=0.5)
        n_req = whole_number(samples, name="samples", lo=0, hi=lti.MAX_SAMPLES) if samples != 0 else 0
        if n_req and n_req < 11:
            raise UnitsError("input.invalid", f"'samples' must be 0 (automatic) or at least 11, got {n_req}", {"param": "samples"})
        use_ss = not is_blank(state_a)
        warnings: list[str] = []
        data: dict[str, Any] = {}
        domain_kind, step_s = domain_and_step(domain, sample_time)
        discrete = domain_kind == "discrete"
        if use_ss:
            if not (is_blank(numerator) and is_blank(denominator)):
                raise UnitsError("input.invalid", "give EITHER numerator/denominator OR state_a/state_b/state_c/state_d, not both", {"param": "state_a"})
            if is_blank(state_b) or is_blank(state_c):
                raise UnitsError("input.missing", "state space needs state_a, state_b and state_c", {"param": "state_b|state_c"})
            a, b, c, d = state_space(state_a, state_b, state_c, state_d)
            poles = lti.ss_poles(a)
            dc = _dc_gain_ss(a, b, c, d, discrete)
            if poles.size:
                real_tol = 1e-9 * np.maximum(1.0, np.abs(poles))
                if discrete:
                    stable = bool(np.all(np.abs(poles) < 1 - 1e-9))
                    boundary = bool(np.any(np.abs(np.abs(poles) - 1) <= 1e-9)) and not np.any(np.abs(poles) > 1 + 1e-9)
                else:
                    stable = bool(np.all(poles.real < -real_tol))
                    boundary = bool(np.any(np.abs(poles.real) <= real_tol)) and not np.any(poles.real > real_tol)
            else:
                stable, boundary = True, False
            verdict = "stable" if stable else ("marginally stable" if boundary else "unstable")
            data["model"] = {"form": "state space", "order": a.shape[0], "stability_method": "numerical: eigenvalues of A (use control_analyze with the transfer function for the exact Routh/Jury test)"}
        else:
            if is_blank(numerator) or is_blank(denominator):
                raise UnitsError("input.missing", "give 'numerator' and 'denominator' (or state_a, state_b, state_c)", {"param": "numerator|denominator"})
            tf = build_tf(numerator, denominator, domain=domain, sample_time=sample_time, require_proper=True)
            poles = poly.roots(tf.den)
            a, b, c, d = lti.tf2ss(tf)
            stab = stability_report(tf.den, tf.dt, poles)
            verdict, stable = stab["verdict"], stab["stable"]
            warnings += stab["_warnings"]
            from eng_toolkit.domains.control.analyze import dc_gain

            gain, _ = dc_gain(tf)
            dc = gain
            data["model"] = {**tf_out(tf), "realisation": "controllable canonical form", "stability_method": stab["method"]["name"]}
            checks = numerical_checks(tf.num, tf.den, poly.roots(tf.num), poles, tf.dt)
            warnings += checks["warnings"]
            data["numerical_checks"] = checks
        order = a.shape[0]
        if order == 0 and kind == "impulse":
            warnings.append("a pure gain has only a Dirac impulse response; nothing is sampled")
        data["stability"] = verdict

        t_final_s = time_value(t_final, name="t_final", lo=1e-9, hi=1e9) if not is_blank(t_final) else None
        n_samples, dt_s, notes = lti.time_grid(poles, discrete=discrete, step=step_s, t_final=t_final_s, samples=n_req or None)
        warnings += notes
        if n_samples > lti.MAX_SAMPLES:
            raise UnitsError(
                "input.out_of_range",
                f"the response needs {n_samples} samples, above the limit {lti.MAX_SAMPLES}; shorten 't_final' or use a larger sample_time",
                {"param": "t_final", "limit_samples": lti.MAX_SAMPLES, "needed": n_samples},
            )
        if n_samples < 2:
            raise UnitsError("input.invalid", "the response needs at least 2 samples", {"param": "t_final"})
        sim = lti.simulate(a, b, c, d, kind=kind, samples=n_samples, step=dt_s, discrete=discrete)
        t, u, y = sim.t, sim.u, sim.y
        if sim.truncated:
            warnings.append(f"the response diverged (exceeded 1e100) and was cut at t = {t[-1]:.6g} s ({len(t)} samples): the system is unstable")
        if len(t) < 2:
            raise UnitsError("input.out_of_range", "the response diverges immediately: the system is far too fast or unstable for the chosen sample step", {"param": "t_final"})
        fast = float(np.abs(poles).max()) if poles.size else 0.0
        if not discrete and fast * dt_s > 0.3:
            warnings.append(
                f"the sample step {dt_s:.3g} s is coarse for the fastest pole (|p| = {fast:.3g} rad/s, {fast * dt_s:.2f} samples per radian): the sample values are exact but "
                "times and peak values taken between samples are approximate; give a shorter t_final or more samples"
            )
        if kind == "impulse" and abs(d) > 0 and not discrete:
            warnings.append("the direct feed-through D adds a Dirac impulse at t = 0 which cannot be sampled; the table shows the smooth part C exp(A t) B only")
        if not discrete and order > 0:
            # consistency of the matrix exponential itself: exp(A h) against exp(A h / 2)^2
            h = float(dt_s)
            full, half = lti.expm(a * h), lti.expm(a * h / 2.0)
            err = float(np.linalg.norm(full - half @ half, np.inf) / max(1.0, np.linalg.norm(full, np.inf)))
            data["matrix_exponential_self_check"] = {"relative_difference_exp(Ah)_vs_exp(Ah/2)^2": err}
            if err > 1e-9:
                warnings.append(f"the matrix exponential is ill-conditioned for this system (self-check difference {err:.1e}); the table may be inaccurate")

        metrics: dict[str, Any] = {}
        values: dict[str, QuantityOut] = {}
        t_unit = "second"
        if kind == "step":
            if stable and dc is not None:
                y_ss = float(dc)
                metrics["steady_state_value"] = y_ss
                metrics["steady_state_error"] = 1.0 - y_ss
                m = lti.step_metrics(t, y, y_ss, tol)
                metrics.update(m)
                if abs(y[-1] - y_ss) > 1e-3 * max(abs(y_ss), 1e-12) + 1e-12:
                    warnings.append(f"the window ends before the response has settled (y at the end {y[-1]:.6g}, final value {y_ss:.6g}); give a longer 't_final' - rise time and settling time may be missing")
                if metrics.get("settling_time") is None and "settling_reason" not in metrics and "reason" not in metrics:
                    metrics["settling_reason"] = "not reached"
            else:
                reason = "unbounded" if verdict == "unstable" else "none (not asymptotically stable)"
                metrics.update(
                    steady_state_value=reason if dc is None or not stable else None,
                    steady_state_error=reason,
                    overshoot_percent="unbounded" if verdict == "unstable" else "undefined (no final value)",
                    rise_time=None,
                    settling_time="unbounded" if verdict == "unstable" else "never (marginal: sustained oscillation or drift)",
                )
                iz = int(np.argmax(np.abs(y)))
                metrics["peak_value"], metrics["peak_time"] = float(y[iz]), float(t[iz])
                if dc is None and stable:
                    metrics["note"] = "an integrator: the step response grows without bound"
        elif kind == "impulse":
            iz = int(np.argmax(np.abs(y)))
            peak = float(y[iz])
            metrics.update(peak_value=peak, peak_time=float(t[iz]), final_value=float(y[-1]))
            if stable and peak != 0.0:
                outside = np.nonzero(np.abs(y) > tol * abs(peak))[0]
                if outside.size == 0:
                    metrics["settling_time"] = 0.0
                elif outside[-1] >= len(y) - 1:
                    metrics["settling_time"] = None
                    metrics["settling_reason"] = "still outside the band at the end of the window"
                else:
                    metrics["settling_time"] = float(t[int(outside[-1]) + 1])
                metrics["settling_definition"] = f"last time |y| exceeds {tol:g} x |peak|"
            else:
                metrics["settling_time"] = "unbounded" if verdict == "unstable" else "never (not asymptotically stable)"
        else:
            err = t - y
            tail = err[-max(2, len(err) // 20) :]
            converged = bool(stable and abs(float(tail.max() - tail.min())) <= 1e-3 * max(1.0, abs(float(tail.mean()))))
            metrics["final_value"] = float(y[-1])
            if converged:
                metrics["steady_state_error_unit_ramp"] = float(tail.mean())
            else:
                metrics["steady_state_error_unit_ramp"] = "unbounded" if verdict != "stable" or abs(float(tail.max() - tail.min())) > 1e-3 else "not converged within the window"
            iz = int(np.argmax(np.abs(y)))
            metrics["peak_value"], metrics["peak_time"] = float(y[iz]), float(t[iz])
            if stable and dc is not None and abs(dc - 1.0) > 1e-9:
                metrics["note"] = "a stable system with DC gain different from 1 follows a ramp with an error that grows like t (1 - DC gain); a finite ramp error needs a loop with an integrator and unit steady-state gain"

        values["peak_value"] = plain(float(metrics["peak_value"]), label="peak_value")
        values["peak_time"] = qty(float(metrics["peak_time"]), t_unit, label="peak_time")
        for key, unit in (("rise_time", t_unit), ("settling_time", t_unit), ("final_value", "dimensionless"), ("steady_state_value", "dimensionless"), ("steady_state_error", "dimensionless")):
            if isinstance(metrics.get(key), (int, float)) and not isinstance(metrics.get(key), bool):
                values[key] = qty(float(metrics[key]), unit, label=key)
        if isinstance(metrics.get("overshoot_percent"), (int, float)):
            values["overshoot"] = qty(float(metrics["overshoot_percent"]), "percent", label="overshoot")
        if isinstance(metrics.get("steady_state_error_unit_ramp"), (int, float)):
            values["steady_state_error_unit_ramp"] = plain(float(metrics["steady_state_error_unit_ramp"]), label="steady_state_error_unit_ramp")

        csv = csv_text(["time_s", "input", "output"], [t, u, y])
        artifact = handle.write_text("response.csv", csv, fmt="csv")
        data.update(
            {
                "input_type": kind,
                "domain": domain_kind,
                "time_grid": {
                    "samples": len(t), "step_s": float(dt_s), "end_s": float(t[-1]), "automatic": t_final_s is None and not n_req,
                    "exact_at_samples": True, "discretisation": "discrete recursion" if discrete else "exact (augmented-system matrix exponential)",
                },
                "metrics": metrics,
                "metric_definitions": {
                    "rise_time": "first time from 10 % to 90 % of the final value (linear interpolation between samples)",
                    "overshoot_percent": "100 (peak - final)/|final|",
                    "settling_time": f"last time the response is outside +/- {tol:g} x |final value| around the final value",
                    "steady_state_value": "DC gain of an asymptotically stable system",
                    "steady_state_error": "1 - final value for a unit step",
                },
                "csv_columns": ["time_s", "input", "output"],
                "preview": {"time_s": [float(x) for x in t[:: max(1, len(t) // 10)][:11]], "output": [float(x) for x in y[:: max(1, len(t) // 10)][:11]]},
            }
        )
        return Computed(values=values, primary="peak_value", warnings=warnings, data=clean(data), artifacts=[artifact])

    return run("control_response", inputs, compute)


__all__ = ["INPUTS", "response", "state_space"]
